package com.hotelmanagement.hms.credit.web; import com.hotelmanagement.hms.credit.dto.*; import com.hotelmanagement.hms.credit.service.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/hotels/{hotel}/branches/{branch}/credit") public class CreditController {private final CreditService s;public CreditController(CreditService s){this.s=s;}@GetMapping("/{customer}")public CreditResponse balance(@PathVariable UUID hotel,@PathVariable UUID branch,@PathVariable UUID customer){return s.balance(hotel,branch,customer);}@PostMapping("/charge")public CreditResponse charge(@PathVariable UUID hotel,@PathVariable UUID branch,@Valid@RequestBody CreditRequest q){return s.charge(hotel,branch,q);}@PostMapping("/settle")public CreditResponse settle(@PathVariable UUID hotel,@PathVariable UUID branch,@Valid@RequestBody CreditRequest q){return s.settle(hotel,branch,q);}}
